// AddonsAddonListItem defines model for addons.addonListItem.
type AddonsAddonListItem struct {
	Description *string `json:"description,omitempty"`
	DisplayName *string `json:"displayName,omitempty"`

	// Enabled Enabled reports whether the addon is enabled (installed and switched on).
	Enabled *bool `json:"enabled,omitempty"`

	// HealthMessage HealthMessage explains an "unhealthy" result (the HTTP status the probe
	// got, or why the endpoint could not be reached). Empty otherwise.
	HealthMessage *string `json:"healthMessage,omitempty"`

	// HealthStatus HealthStatus is whether the running addon is actually working, observed
	// live from an HTTP probe of the addon's service each time this endpoint is
	// called (never persisted). It is orthogonal to LifecycleStatus: an addon
	// can be "installed" yet unhealthy, or "upgrading" while still serving the
	// previous version. "unknown" means an operation is in progress so the addon
	// is not probed; the field is empty for an addon with no live release. Like
	// LifecycleStatus, it is visible to every user who can see the addon.
	HealthStatus *AddonHealthStatus `json:"healthStatus,omitempty"`
	Icon         *string            `json:"icon,omitempty"`

	// Id Example: portal-template
	Id *string `json:"id,omitempty"`

	// LifecycleStatus LifecycleStatus is the addon's Helm release lifecycle state: installing,
	// upgrading, installed, failed or uninstalling. It reports what Portainer's
	// install/upgrade/uninstall operations have done, and is visible to every
	// user who can see the addon (not just admins, unlike Record). It is empty
	// when the addon has no record, i.e. it was never installed.
	//
	// It is NOT a health status. Whether the running addon actually works (pods
	// ready, endpoint responding) is a separate field added later, because the
	// two are independent: an addon can be "installed" but unhealthy, or
	// "upgrading" while still serving healthy traffic on the previous version.
	LifecycleStatus *AddonLifecycleStatus `json:"lifecycleStatus,omitempty"`

	// LifecycleStatusMessage LifecycleStatusMessage explains a failure: why a fresh install failed, or
	// (when LifecycleStatus is "installed") that the last upgrade failed and was
	// rolled back to the version still running. Empty on a clean install/upgrade.
	LifecycleStatusMessage *string `json:"lifecycleStatusMessage,omitempty"`
	Path                   *string `json:"path,omitempty"`

	// Record Record is admin-only: absent from the JSON response for non-admin users.
	Record *AddonsAddonRecord `json:"record,omitempty"`

	// ShortDescription ShortDescription is a one-line tagline for space-constrained UI (the app
	// switcher); Description is the full summary shown in management views.
	ShortDescription *string `json:"shortDescription,omitempty"`
}

